/** 
 * When true, <code>Runtime.getRuntime().halt(0);</code> is used when the JVM shuts down. This prevents Swing shutdown hooks from causing a deadlock and keeping the JVM alive indefinitely. Default is true. 
 */
public void setHaltOnShutdown(boolean halt){
  if (halt) {
    if (shutdownHook != null)     return;
    shutdownHook=new Thread(){
      public void run(){
        try {
          Runtime.getRuntime().halt(0);
        } catch (SecurityException e) {
          e.printStackTrace();
        }
      }
    };
    try {
      Runtime.getRuntime().addShutdownHook(shutdownHook);
    } catch (IllegalStateException | SecurityException e) {
      e.printStackTrace();
    }
  }
 else   if (shutdownHook != null) {
    try {
      Runtime.getRuntime().removeShutdownHook(shutdownHook);
    } catch (IllegalStateException | SecurityException e) {
      e.printStackTrace();
    }
    shutdownHook=null;
  }
}
